var RSVP = require('rsvp')

if (!'assign' in Object) {
  log.info("Object.assign not found, loading polyfill..")
  import(/* webpackChunkName: "objectAssignPolyfill" */ './polyfills/objectAssign')
    .then(() => {
      log.info("loaded Object.assign polyfill")
    })
}

if (!'keys' in Object) {
  log.info("Object.keys not found, loading polyfill..")
  import(/* webpackChunkName: "objectKeysPolyfill" */ './polyfills/objectKeys')
    .then(() => {
      log.info("loaded Object.keys polyfill")
    })
}

// NEXTREV implement / import real logger
var log = {
  debug: function () { },
  info: function () { },
  warn: function () { },
  error: function () { },
}

var api = {
  sendRequest: function (url, payload, options) {
    return new RSVP.Promise(function (resolve, reject) {
      try {
        var client = new Client(url, payload, options)

        client.sendRequest(url, payload, options)
          .then(function (response) {
            resolve(response)
          })
          .catch(function (error) {
            // NEXTREV: implement retry logic
            reject(error)
          })
      } catch (error) {
        log.error('Failed to complete request', error)
        reject(error)
      }
    })
  }
}

var Client = function (url, payload, options) {
  this.url = url
  this.payload = payload
  this.options = options
  this.xhr = this.getXHR()
  this.defaults = {
    timeout: 6000
  }
  this.configurations = {}

  try {
    Object.assign(this.configurations, this.defaults, options)
  } catch (error) {
    log.error(error)
    throw TypeError("Error merging configurations")
  }
}
Client.prototype.getXHR = function () {
  var xhr = new XMLHttpRequest();

  // Look to see if we need to change the xhr object for IE8 + IE9 support
  if (typeof XDomainRequest != 'undefined' && !('withCredentials' in xhr)) {
    log.debug("Detected legacy IE CORS implementation")
    xhr = new XDomainRequest();

    // Check to make sure our xhr obj supports cors
  } else if (!('withCredentials' in xhr)) {
    log.error('CORS not supported by this browser');
    throw TypeError("CORS is unsupported");
  }

  return xhr;
}
Client.prototype.sendRequest = function () {
  var deferredPromise = RSVP.defer()
  var client = this
  var xhr = client.xhr
  var options = client.options
  
  try {
    xhr.open('POST', client.url, true);

    xhr.onerror = function (error) {
      log.error('XHR Error event triggered');
      client.handleError.call(undefined, error, 'error', deferredPromise);
    };
    xhr.ontimeout = function (error) {
      log.error('Timeout error occurred');
      client.handleError.call(undefined, error, 'timeout', deferredPromise);
    };
    xhr.onload = function () {
      client.handleResponse(deferredPromise);
    };

    xhr.timeout = client.configurations.timeout

    // INSIGHT - IE9-8 doesn't support custom headers
    if ('setRequestHeader' in xhr) {
      xhr.setRequestHeader('Content-Type', 'application/json;charset=UTF-8');

      if (options !== undefined && options.headers !== undefined && typeof options.headers === 'object') {
        let keys = Object.keys(options.headers)
        if (keys.length > 0) {
          keys.forEach(key => {
            xhr.setRequestHeader(key, options.headers[key]);
          })
        }
      }
    }

    if (client.payload !== undefined) {
      xhr.send(JSON.stringify(client.payload));
    } else {
      xhr.send();
    }

    // INSIGHT - Setup a safety net timeout for browsers that don't support timeouts or are currently having issues with them (2016 iOS, old browsers, etc). We will add a few millis to the timeout to allow for browsers that support the timeout to properly handle it.
    client.timeoutMonitor = setTimeout(function () {
      // Only abort if the request has not finished
      if (xhr.readyState !== 4) {
        xhr.abort();
        xhr.ontimeout();
      }
    }, client.configurations.timeout + 10);

  } catch (error) {
    log.error('Failed to send request to [' + client.url + '] due to [' + error + ']')
    deferredPromise.reject(error)
  }
  return deferredPromise.promise;
}
Client.prototype.handleError = function (errorMessage, typeOfError, deferredPromise) {
  log.error('Request failure of type [' + typeOfError + '] with error [' + errorMessage + ']')
  deferredPromise.reject({
    errorMessage: errorMessage,
    type: typeOfError
  });
}
Client.prototype.handleResponse = function (deferredPromise) {
  var xhr = this.xhr,
    contentType, responseData;
  
  log.debug('Response received');

  if ('getResponseHeader' in xhr) {
    // Sane browsers
    contentType = xhr.getResponseHeader('Content-Type');
  } else {
    //IE8-9
    contentType = xhr.contentType;
  }

  log.debug('Content-Type: ' + contentType);

  if (contentType === 'application/json') {
    responseData = JSON.parse(xhr.responseText)
  } else {
    responseData = xhr.responseText
  }

  try {
    if (xhr.status !== undefined) {
      if (xhr.status === 200 || xhr.status === 304) {
        log.info("CORS message completed successfully");
        deferredPromise.resolve(responseData);

      } else if (xhr.status >= 500 && xhr.status < 600) {
        log.error('Received a failure HTTP Status Code [' + xhr.status + ']');
        deferredPromise.reject({
          statusCode: xhr.status,
          response: responseData
        })

      } else {
        log.info("CORS message completed in an unexpected state");
        deferredPromise.reject({
          statusCode: xhr.status
        })
      }
    } else {
      // IE8-9
      log.info('IE8-9 - CORS message completed');
      deferredPromise.resolve(responseData);
    }
  } catch (error) {
    log.error('failed while processing response [' + error + ']')
    deferredPromise.reject(error)
  }
}

module.exports = api
module.exports.Client = Client